mapper.sql:
select m.msg_id as source_id, case when c.cmp_id is not null then 'COMPANY' else 'SYSTEM' end as category, case when c.cmp_id is not null then 'COMPANY' when a.apt_id is not null then 'INTERVIEW' else 'SYSTEM' end as thread_type, coalesce(c.cmp_id, a.apt_id, 0) as thread_id, case when c.cmp_id is not null then concat(c.cmp_name, ' · 企业动态') when a.apt_id is not null then concat(coalesce(ac.cmp_name, '企业'), ' · ', coalesce(p.pos_title, '面试'), ' · 面试通知') else '其他通知' end as thread_title, m.msg_title as title, m.msg_content as content, m.msg_created_at as occurred_at, case when m.msg_is_read = 0 then 1 else 0 end as unread_count, 1 as event_count, c.cmp_logo_url as avatar_url, m.msg_target_url as target_url, case when a.apt_id is not null then '面试' else null end as badge from t_msg m left join t_cmp c on m.msg_type = 4 and m.msg_target_url like concat('/companies/', c.cmp_id, '?positionId=%')
left join t_sch_reschedule_request r on r.rsr_requester_id = #{userId} and m.msg_target_url = concat('/candidate/interview/reschedule-requests/', r.rsr_id)
left join t_sch_appointment a on (m.msg_target_url = concat('/candidate/interview/appointments/', a.apt_id) or a.apt_id = r.rsr_appointment_id) and exists (select 1 from t_tal t where t.tal_id = a.apt_candidate_id and t.tal_user_id = #{userId}) left join t_pos p on p.pos_id = a.apt_position_id left join t_cmp ac on ac.cmp_id = p.pos_company_id where m.msg_receiver_id = #{userId}

mapper.select:
select source_id, category, thread_type, thread_id, thread_title as title,
    case when thread_type in ('INTERVIEW', 'SYSTEM') then concat(ranked.title, '：', content) else content end as content,
    occurred_at, total_unread as unread_count, message_count, avatar_url, target_url, badge
from (
    select e.*,
        row_number() over (partition by thread_type, thread_id order by occurred_at desc, source_id desc) as row_num,
        sum(unread_count) over (partition by thread_type, thread_id) as total_unread,
        sum(event_count) over (partition by thread_type, thread_id) as message_count
    from () e
    where category = #{category}
) ranked
where row_num = 1

    and (occurred_at < #{beforeTime}
        or (occurred_at = #{beforeTime} and source_id < #{beforeId})

            or (occurred_at = #{beforeTime} and source_id = #{beforeId} and thread_type < #{beforeType})
        )

order by occurred_at desc, source_id desc, thread_type desc
limit #{limit}

select e.* from () e
where thread_type = #{threadType} and thread_id = #{threadId}
and source_id < #{beforeId}
order by source_id desc limit #{limit}

select source_id from () e
where thread_type = #{threadType} and thread_id = #{threadId} and source_id in
#{id}

mapper.update:
update t_msg set msg_is_read = 1, msg_read_at = coalesce(msg_read_at, now())
where msg_receiver_id = #{userId} and msg_is_read = 0 and msg_id in
#{id}
